mapper.select:
SELECT  FROM TB_SY_NOTI n
WHERE n.rcvr_user_id=#{actor} AND n.noti_dttm >= #{cutoff}
ORDER BY n.noti_dttm DESC, n.noti_id DESC

mapper.update:
UPDATE TB_SY_NOTI n SET read_yn='Y', read_dttm=clock_timestamp(),
  mod_user_id=#{actor}, mod_dttm=clock_timestamp()
WHERE n.noti_id=#{notificationId} AND n.rcvr_user_id=#{actor}
  AND n.read_yn='N' AND n.noti_dttm >= #{cutoff}

UPDATE TB_SY_NOTI n SET read_yn='Y', read_dttm=clock_timestamp(),
  mod_user_id=#{actor}, mod_dttm=clock_timestamp()
WHERE n.rcvr_user_id=#{actor} AND n.read_yn='N' AND n.noti_dttm >= #{cutoff}

mapper.select:
SELECT EXISTS (SELECT 1 FROM TB_SY_NOTI n
  WHERE n.rcvr_user_id=#{recipient} AND n.noti_type_cd=#{type} AND n.link_key=#{targetKey}
    AND (n.noti_dttm AT TIME ZONE 'Asia/Seoul')::date=(#{occurredAt} AT TIME ZONE 'Asia/Seoul')::date)
